import unittest
from candidate import decimal_to_binary

class TestDecimalToBinary(unittest.TestCase):
    def test_normalcase(self):
        self.assertEqual(decimal_to_binary(15), "db1111db")

    def test_zero(self):
        self.assertEqual(decimal_to_binary(0), "db0000db")

    def test_max_value(self):
        self.assertEqual(decimal_to_binary(2**31 - 1), "db2147483647db")

    def test_min_value(self):
        self.assertEqual(decimal_to_binary(-(2**31)), "db-2147483648db")

    def test_negative_numbers(self):
        for i in range(1, 10):
            self.assertEqual(decimal_to_binary(-(2**i)), "db" + "db".join(reversed(bin(abs(-(2**i)))[2:])) + "db")

    def test_large_numbers(self):
        for i in range(10, 32):
            self.assertEqual(decimal_to_binary(2**i), "db" + "db".join(reversed(bin(2**i)[2:])) + "db")

    def test_empty_input(self):
        self.assertEqual(decimal_to_binary(None), "dbdb")

    def test_non_numeric_input(self):
        self.assertEqual(decimal_to_binary("abc"), "dbdb")

if __name__ == '__main__':
    unittest.main()
